package com.arnavgames.tycoon.core.content

import kotlinx.serialization.Serializable

/** Luxury and collections (content/data/luxury.json, generated by tools/content/gen_luxury.py). docs/GDD.md §8. */
@Serializable
data class LuxuryContent(
    val config: LuxuryConfig,
    val categories: List<LuxuryCategoryDef>,
    val showrooms: List<ShowroomDef>,
    val items: List<LuxuryItemDef>,
    val sets: List<CollectionSetDef>,
    val tiers: List<StatusTierDef>,
    val bidders: List<BidderDef>,
) {
    @kotlinx.serialization.Transient val itemById: Map<String, LuxuryItemDef> = items.associateBy { it.id }
    @kotlinx.serialization.Transient val categoryById: Map<String, LuxuryCategoryDef> = categories.associateBy { it.id }
    @kotlinx.serialization.Transient val showroomById: Map<String, ShowroomDef> = showrooms.associateBy { it.id }
    @kotlinx.serialization.Transient val bidderById: Map<String, BidderDef> = bidders.associateBy { it.id }

    companion object {
        val EMPTY = LuxuryContent(LuxuryConfig(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList())
    }
}

@Serializable
data class LuxuryConfig(
    val dealerFee: Double = 0.02,
    /** Dealers buy items back at this share of their current value. */
    val dealerBuyback: Double = 0.85,
    val showroomUpgradeBase: Dollars = com.arnavgames.tycoon.core.money.Money.ZERO,
    val showroomUpgradeGrowth: Double = 6.0,
    /** Each showroom upgrade adds this share of the base capacity. */
    val showroomCapacityStep: Double = 0.5,
    val artCyclePeriodDays: Double = 6.0,
    val artCycleAmplitude: Double = 0.15,
    val auctionEveryHours: Int = 4,
    val auctionMinSeconds: Int = 180,
    val auctionExtendSeconds: Int = 30,
    val auctionBidIncrement: Double = 0.05,
    val auctionOpeningShare: Double = 0.6,
    val auctionBiddersMin: Int = 3,
    val auctionBiddersMax: Int = 5,
    val auctionValuationSd: Double = 0.15,
    val unlocks: Map<String, Int> = mapOf("collection" to 2, "auctions" to 3),
)

@Serializable
data class LuxuryCategoryDef(
    val id: String,
    val name: String,
    val showroom: String,
    val icon: String,
    val driftPerDay: Double,
    val upkeepPerDay: Double,
    val chapter: Int,
    val artCycle: Boolean,
)

@Serializable
data class ShowroomDef(val id: String, val name: String, val icon: String, val baseCapacity: Int)

@Serializable
data class LuxuryItemDef(
    val id: String,
    val name: String,
    /** Parody maker, the artist for museum works, or a kind ("Private island"). */
    val maker: String,
    val category: String,
    val price: Dollars,
    /** common, rare or legendary (rare and legendary items can come up at auction). */
    val rarity: String,
    /** Classic cars appreciate instead of depreciating. */
    val classic: Boolean = false,
    /** Bundled photo (assets path) or null for an illustrated card. */
    val image: String? = null,
    val description: String = "",
    val location: String = "",
    val statusPoints: Double,
)

@Serializable
data class CollectionSetDef(
    val id: String,
    val name: String,
    val items: List<String>,
    /** status, income, dividends, rent or luxuryDiscount. */
    val bonusType: String,
    val bonusValue: Double,
    /** Business id for income bonuses. */
    val bonusTarget: String = "",
    val description: String,
)

@Serializable
data class StatusTierDef(val name: String, val points: Int, val dealerDiscount: Double)

/** A parody billionaire who bids at auctions (docs/GDD.md §1.1). */
@Serializable
data class BidderDef(val id: String, val name: String, val style: String)
